insert into public.workout_templates (slug, name, days_per_week, description, source_note, days) values
  ('ppl-6', 'Push / Pull / Legs', 6, 'Each muscle group twice a week across push, pull and leg days. Intermediate volume.', 'Structure based on commonly documented training splits.', '[{"name": "Push", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "6-8"}, {"name": "Overhead Press", "sets": 3, "reps": "8-10"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Lateral Raise", "sets": 3, "reps": "15"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "12"}, {"name": "Overhead Tricep Extension", "sets": 3, "reps": "12"}]}, {"name": "Pull", "exercises": [{"name": "Deadlift", "sets": 3, "reps": "5"}, {"name": "Pull-Up", "sets": 3, "reps": "8"}, {"name": "Barbell Row", "sets": 3, "reps": "8"}, {"name": "Face Pull", "sets": 3, "reps": "15"}, {"name": "Barbell Curl", "sets": 3, "reps": "10"}, {"name": "Hammer Curl", "sets": 3, "reps": "12"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "6-8"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "8"}, {"name": "Leg Press", "sets": 3, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "12"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "12"}, {"name": "Hanging Leg Raise", "sets": 3, "reps": "12"}]}, {"name": "Push", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "6-8"}, {"name": "Overhead Press", "sets": 3, "reps": "8-10"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Lateral Raise", "sets": 3, "reps": "15"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "12"}, {"name": "Overhead Tricep Extension", "sets": 3, "reps": "12"}]}, {"name": "Pull", "exercises": [{"name": "Deadlift", "sets": 3, "reps": "5"}, {"name": "Pull-Up", "sets": 3, "reps": "8"}, {"name": "Barbell Row", "sets": 3, "reps": "8"}, {"name": "Face Pull", "sets": 3, "reps": "15"}, {"name": "Barbell Curl", "sets": 3, "reps": "10"}, {"name": "Hammer Curl", "sets": 3, "reps": "12"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "6-8"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "8"}, {"name": "Leg Press", "sets": 3, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "12"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "12"}, {"name": "Hanging Leg Raise", "sets": 3, "reps": "12"}]}]'::jsonb),
  ('linear-5x5', '5×5 Linear Progression', 3, 'Three compound lifts per session for 5 sets of 5, adding weight every session.', 'Structure based on commonly documented training splits.', '[{"name": "Workout A", "exercises": [{"name": "Back Squat", "sets": 5, "reps": "5"}, {"name": "Barbell Bench Press", "sets": 5, "reps": "5"}, {"name": "Barbell Row", "sets": 5, "reps": "5"}]}, {"name": "Workout B", "exercises": [{"name": "Back Squat", "sets": 5, "reps": "5"}, {"name": "Overhead Press", "sets": 5, "reps": "5"}, {"name": "Deadlift", "sets": 1, "reps": "5"}]}, {"name": "Workout A", "exercises": [{"name": "Back Squat", "sets": 5, "reps": "5"}, {"name": "Barbell Bench Press", "sets": 5, "reps": "5"}, {"name": "Barbell Row", "sets": 5, "reps": "5"}]}]'::jsonb),
  ('novice-linear-3', '3-Day Novice Linear', 3, 'Low-volume barbell basics for 3 sets of 5. Add weight each session while you can.', 'Structure based on commonly documented training splits.', '[{"name": "Workout A", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5"}, {"name": "Barbell Bench Press", "sets": 3, "reps": "5"}, {"name": "Deadlift", "sets": 1, "reps": "5"}]}, {"name": "Workout B", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5"}, {"name": "Overhead Press", "sets": 3, "reps": "5"}, {"name": "Power Clean", "sets": 5, "reps": "3"}]}, {"name": "Workout A", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5"}, {"name": "Barbell Bench Press", "sets": 3, "reps": "5"}, {"name": "Deadlift", "sets": 1, "reps": "5"}]}]'::jsonb),
  ('power-hyper-ul', 'Power-Hypertrophy Upper/Lower', 4, 'Two heavy low-rep days and two higher-rep size days.', 'Structure based on commonly documented training splits.', '[{"name": "Upper Power", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "3-5"}, {"name": "Barbell Row", "sets": 4, "reps": "3-5"}, {"name": "Overhead Press", "sets": 3, "reps": "6"}, {"name": "Pull-Up", "sets": 3, "reps": "6"}, {"name": "Skull Crusher", "sets": 2, "reps": "8"}, {"name": "Barbell Curl", "sets": 2, "reps": "8"}]}, {"name": "Lower Power", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "3-5"}, {"name": "Deadlift", "sets": 3, "reps": "3-5"}, {"name": "Leg Press", "sets": 3, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "8"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "8"}]}, {"name": "Upper Hypertrophy", "exercises": [{"name": "Incline Dumbbell Press", "sets": 4, "reps": "10"}, {"name": "Cable Fly", "sets": 3, "reps": "12"}, {"name": "Seated Cable Row", "sets": 4, "reps": "10"}, {"name": "Lateral Raise", "sets": 3, "reps": "15"}, {"name": "Dumbbell Curl", "sets": 3, "reps": "12"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "12"}]}, {"name": "Lower Hypertrophy", "exercises": [{"name": "Front Squat", "sets": 3, "reps": "10"}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "10"}, {"name": "Seated Leg Curl", "sets": 3, "reps": "12"}, {"name": "Leg Extension", "sets": 3, "reps": "15"}, {"name": "Seated Calf Raise", "sets": 4, "reps": "15"}]}]'::jsonb),
  ('upper-lower-4', 'Upper / Lower', 4, 'Balanced 4-day split hitting everything twice a week.', 'Structure based on commonly documented training splits.', '[{"name": "Upper A", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "6"}, {"name": "Barbell Row", "sets": 4, "reps": "6"}, {"name": "Overhead Press", "sets": 3, "reps": "8"}, {"name": "Lat Pulldown", "sets": 3, "reps": "10"}, {"name": "Dumbbell Curl", "sets": 2, "reps": "12"}, {"name": "Tricep Pushdown", "sets": 2, "reps": "12"}]}, {"name": "Lower A", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "6"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "8"}, {"name": "Walking Lunge", "sets": 3, "reps": "10"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "12"}, {"name": "Hanging Leg Raise", "sets": 3, "reps": "12"}]}, {"name": "Upper B", "exercises": [{"name": "Incline Barbell Bench Press", "sets": 4, "reps": "8"}, {"name": "Pull-Up", "sets": 4, "reps": "8"}, {"name": "Seated Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Seated Cable Row", "sets": 3, "reps": "10"}, {"name": "Hammer Curl", "sets": 2, "reps": "12"}, {"name": "Skull Crusher", "sets": 2, "reps": "12"}]}, {"name": "Lower B", "exercises": [{"name": "Deadlift", "sets": 3, "reps": "5"}, {"name": "Front Squat", "sets": 3, "reps": "8"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "10"}, {"name": "Hip Thrust", "sets": 3, "reps": "10"}, {"name": "Seated Calf Raise", "sets": 4, "reps": "15"}]}]'::jsonb),
  ('full-body-3', 'Full Body 3×', 3, 'Three full-body sessions with rotating main lifts. Great for busy weeks.', 'Structure based on commonly documented training splits.', '[{"name": "Full Body A", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "8"}, {"name": "Barbell Bench Press", "sets": 3, "reps": "8"}, {"name": "Barbell Row", "sets": 3, "reps": "8"}, {"name": "Lateral Raise", "sets": 2, "reps": "15"}, {"name": "Cable Crunch", "sets": 3, "reps": "12"}]}, {"name": "Full Body B", "exercises": [{"name": "Deadlift", "sets": 3, "reps": "5"}, {"name": "Overhead Press", "sets": 3, "reps": "8"}, {"name": "Lat Pulldown", "sets": 3, "reps": "10"}, {"name": "Walking Lunge", "sets": 2, "reps": "10"}, {"name": "Hanging Leg Raise", "sets": 3, "reps": "12"}]}, {"name": "Full Body C", "exercises": [{"name": "Front Squat", "sets": 3, "reps": "8"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Seated Cable Row", "sets": 3, "reps": "10"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "10"}, {"name": "Dumbbell Curl", "sets": 2, "reps": "12"}]}]'::jsonb),
  ('classic-bro-6', 'Classic Bodybuilding Split', 6, 'Body-part days run twice a week: chest & back, shoulders & arms, legs.', 'Structure based on commonly documented training splits.', '[{"name": "Chest & Back", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "8"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Dumbbell Fly", "sets": 3, "reps": "12"}, {"name": "Pull-Up", "sets": 4, "reps": "8"}, {"name": "Barbell Row", "sets": 4, "reps": "8"}, {"name": "Lat Pulldown", "sets": 3, "reps": "10"}]}, {"name": "Shoulders & Arms", "exercises": [{"name": "Overhead Press", "sets": 4, "reps": "8"}, {"name": "Lateral Raise", "sets": 4, "reps": "12"}, {"name": "Rear Delt Fly", "sets": 3, "reps": "15"}, {"name": "Barbell Curl", "sets": 3, "reps": "10"}, {"name": "Skull Crusher", "sets": 3, "reps": "10"}, {"name": "Hammer Curl", "sets": 3, "reps": "12"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "12"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "8"}, {"name": "Leg Press", "sets": 3, "reps": "12"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "10"}, {"name": "Leg Extension", "sets": 3, "reps": "15"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "12"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "15"}]}, {"name": "Chest & Back", "exercises": [{"name": "Barbell Bench Press", "sets": 4, "reps": "8"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Dumbbell Fly", "sets": 3, "reps": "12"}, {"name": "Pull-Up", "sets": 4, "reps": "8"}, {"name": "Barbell Row", "sets": 4, "reps": "8"}, {"name": "Lat Pulldown", "sets": 3, "reps": "10"}]}, {"name": "Shoulders & Arms", "exercises": [{"name": "Overhead Press", "sets": 4, "reps": "8"}, {"name": "Lateral Raise", "sets": 4, "reps": "12"}, {"name": "Rear Delt Fly", "sets": 3, "reps": "15"}, {"name": "Barbell Curl", "sets": 3, "reps": "10"}, {"name": "Skull Crusher", "sets": 3, "reps": "10"}, {"name": "Hammer Curl", "sets": 3, "reps": "12"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "12"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 4, "reps": "8"}, {"name": "Leg Press", "sets": 3, "reps": "12"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "10"}, {"name": "Leg Extension", "sets": 3, "reps": "15"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "12"}, {"name": "Standing Calf Raise", "sets": 4, "reps": "15"}]}]'::jsonb),
  ('wave-531-4', '5/3/1-Style Wave', 4, 'One main lift per day on a monthly percentage wave (week 1 shown at 75% of training max) plus assistance.', 'Structure based on commonly documented training splits.', '[{"name": "Press Day", "exercises": [{"name": "Overhead Press", "sets": 3, "reps": "5", "pct_1rm": 75}, {"name": "Chest Dip", "sets": 5, "reps": "10"}, {"name": "Chin-Up", "sets": 5, "reps": "10"}]}, {"name": "Deadlift Day", "exercises": [{"name": "Deadlift", "sets": 3, "reps": "5", "pct_1rm": 75}, {"name": "Good Morning", "sets": 5, "reps": "10"}, {"name": "Hanging Leg Raise", "sets": 5, "reps": "15"}]}, {"name": "Bench Day", "exercises": [{"name": "Barbell Bench Press", "sets": 3, "reps": "5", "pct_1rm": 75}, {"name": "Dumbbell Bench Press", "sets": 5, "reps": "10"}, {"name": "One-Arm Dumbbell Row", "sets": 5, "reps": "10"}]}, {"name": "Squat Day", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5", "pct_1rm": 75}, {"name": "Leg Press", "sets": 5, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 5, "reps": "10"}]}]'::jsonb),
  ('tiered-t1t2t3', 'Tiered T1/T2/T3 Progression', 3, 'Heavy tier-1 lift, moderate tier-2, light high-rep tier-3 each day.', 'Structure based on commonly documented training splits.', '[{"name": "Day 1", "exercises": [{"name": "Back Squat", "sets": 5, "reps": "3"}, {"name": "Barbell Bench Press", "sets": 3, "reps": "10"}, {"name": "Lat Pulldown", "sets": 3, "reps": "15"}]}, {"name": "Day 2", "exercises": [{"name": "Overhead Press", "sets": 5, "reps": "3"}, {"name": "Deadlift", "sets": 3, "reps": "10"}, {"name": "One-Arm Dumbbell Row", "sets": 3, "reps": "15"}]}, {"name": "Day 3", "exercises": [{"name": "Barbell Bench Press", "sets": 5, "reps": "3"}, {"name": "Back Squat", "sets": 3, "reps": "10"}, {"name": "Lat Pulldown", "sets": 3, "reps": "15"}]}]'::jsonb),
  ('high-freq-ppl', 'High-Frequency PPL (beginner)', 6, 'Beginner push/pull/legs run twice a week with simple linear progression.', 'Structure based on commonly documented training splits.', '[{"name": "Push", "exercises": [{"name": "Barbell Bench Press", "sets": 3, "reps": "5"}, {"name": "Overhead Press", "sets": 3, "reps": "8"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "10"}, {"name": "Lateral Raise", "sets": 3, "reps": "15"}]}, {"name": "Pull", "exercises": [{"name": "Deadlift", "sets": 1, "reps": "5"}, {"name": "Barbell Row", "sets": 3, "reps": "5"}, {"name": "Pull-Up", "sets": 3, "reps": "8"}, {"name": "Face Pull", "sets": 5, "reps": "15"}, {"name": "Hammer Curl", "sets": 4, "reps": "10"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "10"}, {"name": "Leg Press", "sets": 3, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "10"}, {"name": "Standing Calf Raise", "sets": 5, "reps": "10"}]}, {"name": "Push", "exercises": [{"name": "Barbell Bench Press", "sets": 3, "reps": "5"}, {"name": "Overhead Press", "sets": 3, "reps": "8"}, {"name": "Incline Dumbbell Press", "sets": 3, "reps": "10"}, {"name": "Tricep Pushdown", "sets": 3, "reps": "10"}, {"name": "Lateral Raise", "sets": 3, "reps": "15"}]}, {"name": "Pull", "exercises": [{"name": "Deadlift", "sets": 1, "reps": "5"}, {"name": "Barbell Row", "sets": 3, "reps": "5"}, {"name": "Pull-Up", "sets": 3, "reps": "8"}, {"name": "Face Pull", "sets": 5, "reps": "15"}, {"name": "Hammer Curl", "sets": 4, "reps": "10"}]}, {"name": "Legs", "exercises": [{"name": "Back Squat", "sets": 3, "reps": "5"}, {"name": "Romanian Deadlift", "sets": 3, "reps": "10"}, {"name": "Leg Press", "sets": 3, "reps": "10"}, {"name": "Lying Leg Curl", "sets": 3, "reps": "10"}, {"name": "Standing Calf Raise", "sets": 5, "reps": "10"}]}]'::jsonb)
